     *		 rethrown wrapped into a PropelException.
     */
    public static function doSelectJoinAllExceptDocumentacion(Criteria $criteria, $con = null, $join_behavior = Criteria::LEFT_JOIN)
    {
        $criteria = clone $criteria;

        // Set the correct dbName if it has not been overridden
        // $criteria->getDbName() will return the same object if not set to another value
        // so == check is okay and faster
        if ($criteria->getDbName() == Propel::getDefaultDB()) {
            $criteria->setDbName(RegistrosPeer::DATABASE_NAME);
        }

        RegistrosPeer::addSelectColumns($criteria);
        $startcol2 = RegistrosPeer::NUM_HYDRATE_COLUMNS;

        TipoEscalaPeer::addSelectColumns($criteria);
        $startcol3 = $startcol2 + TipoEscalaPeer::NUM_HYDRATE_COLUMNS;

        CategoriaEscalaPeer::addSelectColumns($criteria);
        $startcol4 = $startcol3 + CategoriaEscalaPeer::NUM_HYDRATE_COLUMNS;

        EspecialidadRegistroPeer::addSelectColumns($criteria);
        $startcol5 = $startcol4 + EspecialidadRegistroPeer::NUM_HYDRATE_COLUMNS;

        $criteria->addJoin(RegistrosPeer::TIPOESCALA_ID, TipoEscalaPeer::TIPOESCALA_ID, $join_behavior);

        $criteria->addJoin(RegistrosPeer::CATEGORIAESCALA_ID, CategoriaEscalaPeer::CATEGORIAESCALA_ID, $join_behavior);

        $criteria->addJoin(RegistrosPeer::ESPECIALIDADREGISTRO_ID, EspecialidadRegistroPeer::ESPECIALIDADREGISTRO_ID, $join_behavior);

        // symfony_behaviors behavior
        foreach (sfMixer::getCallables(self::getMixerPreSelectHook(__FUNCTION__)) as $sf_hook)
        {
          call_user_func($sf_hook, 'BaseRegistrosPeer', $criteria, $con);
        }


        $stmt = BasePeer::doSelect($criteria, $con);
        $results = array();

        while ($row = $stmt->fetch(PDO::FETCH_NUM)) {
            $key1 = RegistrosPeer::getPrimaryKeyHashFromRow($row, 0);
            if (null !== ($obj1 = RegistrosPeer::getInstanceFromPool($key1))) {
                // We no longer rehydrate the object, since this can cause data loss.
                // See http://www.propelorm.org/ticket/509
                // $obj1->hydrate($row, 0, true); // rehydrate
            } else {
                $cls = RegistrosPeer::getOMClass();

                $obj1 = new $cls();
                $obj1->hydrate($row);
                RegistrosPeer::addInstanceToPool($obj1, $key1);
            } // if obj1 already loaded

                // Add objects for joined TipoEscala rows

                $key2 = TipoEscalaPeer::getPrimaryKeyHashFromRow($row, $startcol2);
                if ($key2 !== null) {
                    $obj2 = TipoEscalaPeer::getInstanceFromPool($key2);
                    if (!$obj2) {
    
                        $cls = TipoEscalaPeer::getOMClass();

                    $obj2 = new $cls();
                    $obj2->hydrate($row, $startcol2);
                    TipoEscalaPeer::addInstanceToPool($obj2, $key2);
                } // if $obj2 already loaded

                // Add the $obj1 (Registros) to the collection in $obj2 (TipoEscala)
                $obj2->addRegistros($obj1);

            } // if joined row is not null

                // Add objects for joined CategoriaEscala rows

                $key3 = CategoriaEscalaPeer::getPrimaryKeyHashFromRow($row, $startcol3);
                if ($key3 !== null) {
                    $obj3 = CategoriaEscalaPeer::getInstanceFromPool($key3);
                    if (!$obj3) {
    
                        $cls = CategoriaEscalaPeer::getOMClass();

                    $obj3 = new $cls();
                    $obj3->hydrate($row, $startcol3);
                    CategoriaEscalaPeer::addInstanceToPool($obj3, $key3);
                } // if $obj3 already loaded

                // Add the $obj1 (Registros) to the collection in $obj3 (CategoriaEscala)
                $obj3->addRegistros($obj1);

            } // if joined row is not null

                // Add objects for joined EspecialidadRegistro rows

                $key4 = EspecialidadRegistroPeer::getPrimaryKeyHashFromRow($row, $startcol4);
                if ($key4 !== null) {
                    $obj4 = EspecialidadRegistroPeer::getInstanceFromPool($key4);
                    if (!$obj4) {
    
                        $cls = EspecialidadRegistroPeer::getOMClass();

                    $obj4 = new $cls();
                    $obj4->hydrate($row, $startcol4);
                    EspecialidadRegistroPeer::addInstanceToPool($obj4, $key4);
                } // if $obj4 already loaded

                // Add the $obj1 (Registros) to the collection in $obj4 (EspecialidadRegistro)
                $obj4->addRegistros($obj1);

            } // if joined row is not null

            $results[] = $obj1;
        }
        $stmt->closeCursor();

        return $results;
    }


